local ParkTaskCellNode = Class('ParkTaskCellNode')

function ParkTaskCellNode:__init()
    self._data = nil
    self._cb = nil
end

function ParkTaskCellNode:__delete()
    self._data = nil
    self._cb = nil
end

function ParkTaskCellNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnClick))
end

function ParkTaskCellNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb
    self:FillSelf()
end

function ParkTaskCellNode:FillSelf()
    local data = self._data
    local isCanDraw = checkNumber(data.status) == 1 ---可领取
    local isDraw = checkNumber(data.status) == 2 ---已领取
    CfUtils.SetUISwitchImage(self.BgTexture2, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.BgTexture1, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgDecorate, isCanDraw and 2 or 1)
    CfUtils.SetUISwitchImage(self.ImgREN, isDraw and 2 or 1)
    ---@type ActivityPtDayTaskVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6451, "ActivityPtDayTaskVo", data.id)
    CfUtils.FillText(self.NameTxt, data.desc)
    self.Slider.value = checkNumber(data.progress) / checkNumber(data.targetNum)
    CfUtils.FillText(self.TitleText, localize("<size=30><color=#545454>_num1_</color></size>/_num2_", {_num1_ = data.progress, _num2_ = data.targetNum}))

    CfUtils.SetActive(self.HasReceived, isDraw)
    CfUtils.SetActive(self.FontStyleButton, not isDraw)
    local fontStyleBtn = KTool.GetComponent(self.FontStyleButton.gameObject ,typeof(CS.Game.Native.Common.FontStyleButton) )
    if isCanDraw and not isDraw then
        fontStyleBtn:ResetFontStyle("B12" , localize("领取"))
        KTool.SetActive(fontStyleBtn , true)
    elseif (not isDraw) then
        fontStyleBtn:ResetFontStyle("B13" , localize("前往"))
        KTool.SetActive(fontStyleBtn.gameObject , (not (checkInt(vo.openType)  <= 0)))
    else
        KTool.SetActive(fontStyleBtn.gameObject , false)
    end
    CfUtils.SetActive(self.TextUnderway, not isDraw and not isCanDraw and (checkInt(vo.openType) <= 0))

    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsListLight")
    if scr then
        scr:FreshBaseUI(data.rewards)
        --scr:FreshBaseUI(data.rewards, false)
        scr:SetIsGetMaskShow(isDraw)
    end
end

function ParkTaskCellNode:OnClick()
    local isCanDraw = checkNumber(self._data.status) == 1
    local isDraw = checkNumber(self._data.status) == 2

    if isDraw then
        GameUtils.Toast(localize("已领取"))
        return
    end
    if not isCanDraw then
        local vo = self:GetActivityPtTaskVo(self._data.id)
        if checkInt(vo.openType) > 0 then
            cs_coroutine.start(function()
                local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(vo.openType)
                local t = checkTable(CfUtils.Split(vo.openParameter))
                GoodsConfMgr:GetInstance():ExecuteJump(row, nil, nil, nil, t)
            end)
        end
    else
        if not self._cb then
            return
        end
        self._cb()
    end
end

function ParkTaskCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ParkTaskCellNode